# Source for q/spi-waves.js: Waves (incl. pulsed echo), Physics (interactions), Attenuation.
W="Waves"; P="Physics"; A="Attenuation"
Q=[
# --- Sound basics ---
(W,"Sound is best described as a:","Mechanical, longitudinal wave",["Electromagnetic, transverse wave","Mechanical, transverse wave","Electromagnetic, longitudinal wave"],"Sound needs a medium and its particles vibrate in the same direction the wave travels.","F"),
(W,"Sound cannot travel through:","A vacuum",["Water","Bone","Air"],"Sound is mechanical: it needs particles to compress and spread apart.","F"),
(W,"Regions of high pressure and density in a sound wave are called:","Compressions",["Rarefactions","Troughs","Nodes"],"Compressions are high-pressure regions; rarefactions are low-pressure regions.","F"),
(W,"Which is NOT one of the acoustic variables?","Frequency",["Pressure","Density","Distance (particle motion)"],"Acoustic variables are what change as sound passes: pressure, density and particle distance (some texts add temperature). Frequency is a wave parameter.","F"),
(W,"Ultrasound is sound with a frequency above:","20 kHz",["20 Hz","2 MHz","20 MHz"],"Humans hear about 20 Hz to 20 kHz. Below 20 Hz is infrasound.","F"),
(W,"Diagnostic medical ultrasound commonly uses frequencies of about:","2 to 15 MHz",["20 to 200 Hz","20 to 50 kHz","100 to 500 MHz"],"Lower frequencies penetrate deeper; higher frequencies give better resolution for shallow structures.","F"),
# --- Parameters ---
(W,"Which wave parameter is determined by BOTH the sound source and the medium?","Wavelength",["Frequency","Period","Propagation speed"],"Wavelength = propagation speed ÷ frequency, so it depends on the medium (speed) and the source (frequency).","F"),
(W,"Propagation speed is determined by:","The medium only",["The sound source only","Both source and medium","The sonographer"],"Speed depends on the medium's stiffness and density, not on frequency or amplitude.","F"),
(W,"Frequency and period are determined by:","The sound source",["The medium","Both source and medium","The receiver"],"The transducer sets frequency and period. They do not change as sound passes into a new medium.","F"),
(W,"Which parameters can the sonographer change during imaging?","Amplitude, power and intensity",["Propagation speed","Wavelength of a given transducer in a given tissue","Period of a pulsed transducer"],"Adjusting output power changes the strength-related parameters. Speed is fixed by the tissue.","F"),
(W,"Period and frequency are related how?","Inversely: period × frequency = 1",["Directly proportional","Unrelated","Period = frequency squared"],"Doubling frequency halves the period.","F"),
(W,"The period of a 2 MHz wave is:","0.5 µs",["2 µs","0.2 µs","5 µs"],"Period = 1 ÷ frequency = 1 ÷ 2,000,000 s = 0.5 µs.","F"),
(W,"The wavelength of a 3 MHz wave in soft tissue is about:","0.51 mm",["1.54 mm","0.31 mm","4.6 mm"],"λ (mm) = 1.54 ÷ f (MHz) = 1.54 ÷ 3 ≈ 0.51 mm.","F"),
(W,"If frequency is doubled in the same tissue, wavelength:","Halves",["Doubles","Stays the same","Quadruples"],"Speed is fixed by the medium, so wavelength and frequency are inversely related.","F"),
(W,"Propagation speed increases when a medium is:","Stiffer",["Denser, with stiffness unchanged","More compressible","Hotter in all cases"],"Stiffness (resistance to compression) raises speed. Density alone lowers it. Bone is very stiff, so sound is fast in bone.","F"),
(W,"Rank propagation speeds from slowest to fastest:","Lung, fat, soft tissue, bone",["Bone, soft tissue, fat, lung","Fat, lung, bone, soft tissue","Soft tissue, lung, fat, bone"],"Approximate speeds: lung about 500 m/s, fat 1450, soft tissue 1540, bone 2000 to 4000 m/s.","F"),
(W,"The speed of sound in air is about:","330 m/s",["1540 m/s","3500 m/s","50 m/s"],"Air is very compressible, so sound travels slowly in it.","F"),
(W,"The speed of sound in bone is about:","2000 to 4000 m/s",["330 m/s","1450 m/s","1540 m/s"],"Bone is stiff, so it carries sound fastest of the body's tissues.","F"),
(W,"Sound travels from soft tissue into fat. Which changes?","Speed and wavelength; frequency stays the same",["Frequency only","Frequency and speed","Nothing changes"],"Frequency is set by the source. In slower fat, the wavelength shortens.","C"),
(W,"Amplitude is the:","Maximum change of an acoustic variable from its average value",["Distance between compressions","Time for one cycle","Number of cycles per second"],"Amplitude is measured from the baseline to the peak, often in pressure units or decibels.","F"),
(W,"Power is proportional to:","Amplitude squared",["Amplitude","Frequency","Wavelength"],"Doubling amplitude quadruples power.","F"),
(W,"Intensity is defined as:","Power ÷ beam area",["Power × beam area","Amplitude ÷ time","Frequency × wavelength"],"Intensity (W/cm²) is concentrated power. Focusing raises intensity by shrinking the area.","F"),
(W,"If the beam area is halved while power stays constant, intensity:","Doubles",["Halves","Is unchanged","Quadruples"],"Intensity = power ÷ area.","F"),
(W,"If amplitude is tripled, intensity:","Increases 9 times",["Triples","Increases 6 times","Is unchanged"],"Intensity is proportional to amplitude squared: 3² = 9.","C"),
(W,"Constructive interference occurs when two waves are:","In phase",["Out of phase","Of different media","Perpendicular"],"In-phase waves add to make a bigger wave. Out-of-phase waves partly or fully cancel (destructive interference).","F"),
# --- Pulsed wave ---
(W,"Pulse duration equals:","Number of cycles in the pulse × period",["Number of cycles × wavelength","PRF × period","Duty factor × PRP"],"Pulse duration is the time the pulse is 'on', usually 0.5 to 3 µs in imaging.","F"),
(W,"Pulse repetition period (PRP) is:","The time from the start of one pulse to the start of the next",["The time the transducer is transmitting","The length of one pulse","The time for one cycle"],"PRP includes the transmit time and the much longer listening time.","F"),
(W,"PRP and PRF depend on:","Imaging depth",["Transducer frequency","Number of cycles","Propagation speed alone"],"The machine must wait for echoes from the deepest point before the next pulse, so deeper imaging lengthens PRP and lowers PRF.","F"),
(W,"When imaging depth is increased, PRF:","Decreases",["Increases","Stays the same","Doubles"],"More listening time per pulse means fewer pulses each second.","F"),
(W,"Maximum PRF for an imaging depth of 10 cm is about:","7,700 Hz",["77,000 Hz","770 Hz","13,000 Hz"],"PRF (Hz) ≈ 77,000 ÷ depth (cm) = 7,700 Hz.","C"),
(W,"PRP for a depth of 8 cm is about:","104 µs",["13 µs","8 µs","1,040 µs"],"PRP (µs) = 13 × depth (cm) = 13 × 8 = 104 µs.","C"),
(W,"Duty factor is:","The fraction of time the transducer is transmitting",["The fraction of time spent listening","PRF ÷ frequency","The number of pulses per second"],"Duty factor = pulse duration ÷ PRP. Imaging duty factors are very low, about 0.1 to 1%.","F"),
(W,"The duty factor of continuous-wave ultrasound is:","100% (1.0)",["0%","50%","About 1%"],"CW transmits all the time.","F"),
(W,"Increasing imaging depth makes the duty factor:","Smaller",["Larger","Unchanged","100%"],"Pulse duration is unchanged, but PRP lengthens, so the fraction of time transmitting falls.","F"),
(W,"A pulse lasts 2 µs and the PRP is 200 µs. What is the duty factor?","1%",["10%","0.1%","100%"],"DF = 2 ÷ 200 = 0.01 = 1%.","C"),
(W,"Typical PRF in diagnostic imaging is about:","1 to 10 kHz",["1 to 10 MHz","1 to 10 Hz","1 to 10 GHz"],"PRF is thousands of pulses per second, far lower than the MHz transducer frequency.","F"),
(W,"Spatial pulse length is determined by:","Both the source and the medium",["The source only","The medium only","The sonographer"],"SPL = cycles × wavelength, and wavelength depends on both.","F"),
(W,"Which pulse parameter can the sonographer change by adjusting depth?","PRF and PRP",["Pulse duration","Spatial pulse length","Wavelength"],"Pulse duration and SPL are set by the transducer. Depth controls the time between pulses.","F"),
# --- Range equation ---
(W,"The range equation calculates reflector depth from:","Go-return time and the speed of sound",["Frequency and wavelength","Amplitude and power","PRF and duty factor"],"Depth = (speed × time) ÷ 2, because the pulse travels to the reflector and back.","F"),
(W,"The '13 microsecond rule' means:","Each 13 µs of go-return time corresponds to 1 cm of depth in soft tissue",["Each pulse lasts 13 µs","The PRF is 13 kHz","Sound travels 13 cm per µs"],"Sound at 1.54 mm/µs takes 13 µs to travel 2 cm (1 cm down and back).","F"),
(W,"An echo returns 65 µs after the pulse is sent. How deep is the reflector?","5 cm",["13 cm","2.5 cm","10 cm"],"65 ÷ 13 = 5 cm.","F"),
(W,"A reflector is 12 cm deep. What is the go-return time?","156 µs",["78 µs","12 µs","312 µs"],"13 µs × 12 cm = 156 µs.","F"),
(W,"The machine assumes 1540 m/s. If sound actually travels faster in a tissue, the reflector is displayed:","Shallower than its true depth",["Deeper than its true depth","At the correct depth","Twice"],"Echoes return sooner than expected, so the machine places them too close. This is speed error (range error) artifact.","C"),
# --- Intensities ---
(W,"Which intensity is the highest value for a given pulsed beam?","SPTP (spatial peak, temporal peak)",["SATA","SPTA","SATP"],"Spatial peak is at the beam center and temporal peak is during the pulse, so SPTP is the largest.","F"),
(W,"Which intensity is the lowest for a pulsed beam?","SATA (spatial average, temporal average)",["SPTP","SPTA","SPPA"],"Averaging over both the beam area and the whole pulse repetition period gives the smallest value.","F"),
(W,"The intensity most closely related to tissue heating is:","SPTA",["SATA","SATP","SPTP"],"Spatial peak, temporal average intensity reflects how much energy is delivered over time at the beam's hottest point.","F"),
(W,"The beam uniformity ratio (SP/SA factor) describes:","How concentrated the intensity is at the beam center compared with the average",["The duty factor","The bandwidth","The frame rate"],"SP/SA is always 1 or more. A larger value means intensity is more concentrated at the center.","C"),
(W,"For continuous-wave ultrasound, temporal peak and temporal average intensities are:","Equal",["Very different","Zero","Unrelated"],"With a 100% duty factor, the beam never switches off, so peak and average over time are the same.","C"),
# --- Reflection and impedance ---
(P,"Acoustic impedance (Z) equals:","Density × propagation speed",["Density ÷ propagation speed","Frequency × wavelength","Amplitude²"],"Impedance is measured in rayls. It describes how much a medium resists sound passing through.","F"),
(P,"A reflection occurs at a boundary at normal incidence when:","The two media have different acoustic impedances",["The two media have different frequencies","The angle is oblique only","The media have the same impedance"],"At normal incidence, reflection needs an impedance mismatch. The bigger the mismatch, the stronger the echo.","F"),
(P,"If two tissues have identical impedances, at normal incidence:","All the sound is transmitted and none is reflected",["All the sound is reflected","Half is reflected","The sound is refracted"],"With no impedance difference there is no echo, even if the tissues look different under a microscope.","F"),
(P,"The intensity reflection coefficient at normal incidence is calculated as:","((Z₂ − Z₁) ÷ (Z₂ + Z₁))²",["(Z₂ − Z₁) ÷ Z₁","Z₂ ÷ Z₁","(Z₂ + Z₁)²"],"The fraction reflected depends on the impedance mismatch.","F"),
(P,"Impedances are 4 and 6 rayls. What percentage of intensity is reflected at normal incidence?","4%",["20%","2%","40%"],"((6 − 4) ÷ (6 + 4))² = (0.2)² = 0.04 = 4%. The remaining 96% is transmitted.","C"),
(P,"At a soft tissue to soft tissue boundary, about how much intensity is reflected?","Less than 1%",["About 50%","About 99%","100%"],"Soft tissue impedances are similar, so most sound passes through, letting us image deep structures.","F"),
(P,"At a soft tissue to air boundary, about how much intensity is reflected?","About 99.9%",["About 1%","About 50%","None"],"The huge impedance mismatch reflects nearly everything, which is why lung and bowel gas block imaging.","F"),
(P,"If 15% of intensity is reflected at a boundary, how much is transmitted?","85%",["15%","100%","0%"],"Energy is conserved: transmitted = 100% − reflected.","F"),
(P,"Specular reflection occurs when the boundary is:","Smooth and large compared with the wavelength",["Rough and irregular","Smaller than the wavelength","Moving"],"Specular reflectors, such as the diaphragm or valve leaflets, reflect strongly in one direction and are angle dependent.","F"),
(P,"Specular reflectors appear brightest when the beam strikes them:","At 90° (perpendicular)",["At a shallow, glancing angle","Parallel to the surface","At any angle equally"],"Perpendicular incidence sends the echo straight back to the transducer.","F"),
(P,"Backscatter (diffuse reflection) comes from:","Rough or irregular surfaces, scattering sound in many directions",["Smooth large boundaries","Reflectors much smaller than the wavelength only","Air only"],"Backscatter gives organs their texture and is less angle dependent than specular reflection.","F"),
(P,"Rayleigh scattering occurs when the reflector is:","Much smaller than the wavelength, such as red blood cells",["Much larger than the wavelength","Smooth and flat","Made of bone"],"Rayleigh scatterers send sound equally in all directions. This weak scatter from blood is what Doppler detects.","F"),
(P,"Rayleigh scattering is proportional to:","Frequency to the fourth power",["Frequency","Frequency squared","Wavelength"],"Doubling frequency increases Rayleigh scattering 16 times.","C"),
(P,"Refraction is:","A change in direction of sound as it crosses a boundary",["A reflection back to the transducer","A loss of energy as heat","Spreading of the beam"],"Refraction follows Snell's law and needs oblique incidence and different propagation speeds.","F"),
(P,"At normal incidence, refraction:","Does not occur",["Always occurs","Occurs only in bone","Occurs if impedances differ"],"Refraction needs oblique incidence.","F"),
(P,"Snell's law relates the angle of transmission to:","The angle of incidence and the propagation speeds of the two media",["Impedances only","Frequency and wavelength","Amplitude and power"],"sin(transmission angle) ÷ sin(incidence angle) = speed in medium 2 ÷ speed in medium 1.","F"),
(P,"Sound crosses obliquely from a slower medium into a faster one. The transmission angle is:","Larger than the incidence angle",["Smaller than the incidence angle","Equal to the incidence angle","Zero"],"Sound bends away from the perpendicular when it speeds up.","C"),
(P,"At oblique incidence, the angle of reflection:","Equals the angle of incidence",["Is always 90°","Is double the incidence angle","Depends on frequency"],"Like light on a mirror, the reflected angle matches the incidence angle.","F"),
(P,"Refraction can cause which artifact?","A structure displayed side by side with its copy (ghost image)",["Shadowing only","Reverberation","Mirror image across the diaphragm"],"Bending of the beam makes the machine place the echo in the wrong lateral position, sometimes creating a duplicate.","F"),
(P,"Sound strikes a boundary at an oblique angle, but both media have the same propagation speed. What happens to the transmitted beam?","It continues straight, without bending",["It bends toward the perpendicular","It bends away from the perpendicular","It is completely reflected"],"Refraction needs both oblique incidence and a change in speed. With equal speeds, the transmitted beam does not bend.","C"),
(P,"A lens on a transducer focuses the beam using:","Refraction",["Reflection","Attenuation","Absorption"],"The lens material has a different speed of sound, so it bends the beam toward a focus.","C"),
(P,"Which interface produces the strongest echo?","Soft tissue and bone",["Liver and kidney","Fat and muscle","Blood and myocardium"],"The large impedance difference between soft tissue and bone reflects much of the sound, causing bright echoes and shadowing.","F"),
(P,"Echogenicity of a tissue depends mainly on:","Impedance differences and scattering within it",["Its temperature","Its color","Its blood type"],"Uniform fluid with no interfaces is anechoic. Tissues with many scatterers and interfaces are more echogenic.","F"),
(P,"Fluid such as blood in a chamber usually appears:","Anechoic (black) at normal gain",["Hyperechoic","The same as myocardium","Brighter than bone"],"Red cells scatter very weakly, so the cavity looks black on B-mode. Very slow flow can show swirling smoke (spontaneous echo contrast).","F"),
# --- Attenuation ---
(A,"Attenuation is:","The weakening of sound as it travels",["Bending of sound at a boundary","An increase in frequency","Beam focusing"],"Sound loses amplitude, power and intensity with distance.","F"),
(A,"The three components of attenuation are:","Absorption, reflection and scattering",["Refraction, interference and focusing","Compression, rarefaction and propagation","Frequency, period and wavelength"],"Energy leaves the beam by being converted to heat, reflected away or scattered.","F"),
(A,"In soft tissue, the main cause of attenuation is:","Absorption (conversion to heat)",["Reflection","Refraction","Interference"],"Most energy lost in soft tissue becomes heat.","F"),
(A,"Attenuation is expressed in:","Decibels (dB)",["Rayls","Hertz","Watts only"],"Decibels describe relative change on a logarithmic scale.","F"),
(A,"Attenuation increases with:","Higher frequency and longer path length",["Lower frequency","Shorter path length","Lower power"],"Higher frequencies are absorbed more, which is why they penetrate less.","F"),
(A,"The attenuation coefficient in soft tissue is about:","0.5 dB per cm per MHz",["5 dB per cm per MHz","0.05 dB per cm per MHz","1540 dB per cm"],"Multiply by frequency for dB/cm, then by distance for total attenuation.","F"),
(A,"A 3 MHz beam travels 6 cm through soft tissue (one way). What is the total attenuation?","9 dB",["18 dB","3 dB","4.5 dB"],"Coefficient = 0.5 × 3 = 1.5 dB/cm. 1.5 × 6 = 9 dB.","C"),
(A,"A decrease of 3 dB means intensity has:","Halved",["Doubled","Fallen to one tenth","Not changed"],"−3 dB halves intensity; +3 dB doubles it.","F"),
(A,"A decrease of 10 dB means intensity has fallen to:","One tenth of its original value",["Half","One third","Zero"],"−10 dB = 1/10; −20 dB = 1/100.","F"),
(A,"Intensity increases from 2 W/cm² to 8 W/cm². What is the change in decibels?","+6 dB",["+3 dB","+10 dB","+4 dB"],"Doubling twice (2 → 4 → 8) is 3 + 3 = 6 dB.","C"),
(A,"Half-value layer thickness is:","The depth at which intensity falls to half its original value",["Half the wavelength","Half the transducer diameter","The depth of the focus"],"Also called penetration depth or half-boundary layer. It corresponds to 3 dB of attenuation.","F"),
(A,"Half-value layer thickness is smaller (thinner) when:","Frequency is higher",["Frequency is lower","The medium is water","Power is increased"],"Higher frequency attenuates faster, so intensity halves over a shorter distance.","F"),
(A,"Which medium has the LOWEST attenuation?","Water",["Bone","Lung","Muscle"],"Water and fluids (blood, urine, bile) attenuate very little, which is why tissue behind them looks bright (enhancement).","F"),
(A,"Which medium has the HIGHEST attenuation?","Lung (air)",["Water","Blood","Fat"],"Air attenuates sound extremely strongly, followed by bone.","F"),
(A,"Attenuation is the reason a deeper structure:","Returns weaker echoes, needing time gain compensation",["Returns stronger echoes","Has a higher frequency","Appears closer than it is"],"TGC boosts amplification for later (deeper) echoes to make the image uniform.","F"),
(A,"Attenuation is related to frequency in soft tissue how?","Directly proportional",["Inversely proportional","Unrelated","Proportional to the square root"],"In soft tissue, attenuation in dB rises roughly in step with frequency.","F"),
(A,"Why is a 2.5 MHz transducer used for a large adult instead of 7 MHz?","Lower frequency attenuates less and penetrates deeper",["Lower frequency gives better resolution","Higher frequency cannot be used in the chest","Lower frequency has a higher PRF"],"Penetration is traded for resolution. Deep structures need lower frequencies.","F"),
(A,"Posterior acoustic shadowing occurs behind structures that:","Attenuate strongly, such as bone, calcium or gas",["Attenuate weakly, such as fluid","Are perfectly smooth","Are moving"],"Little sound passes beyond them, so the area behind looks dark.","F"),
(A,"Acoustic enhancement occurs behind structures that:","Attenuate less than surrounding tissue, such as fluid-filled cysts",["Attenuate more than surrounding tissue","Reflect all sound","Are calcified"],"More sound reaches the deeper tissue, so it looks brighter than tissue at the same depth beside it.","F"),
(A,"Total attenuation of 30 dB means intensity has fallen to:","One thousandth of its original value",["One thirtieth","One third","One hundredth"],"Each 10 dB is a factor of 10: 10 × 10 × 10 = 1000.","C"),
(A,"In echocardiography, the posterior pericardium often appears very bright because:","It is a strong specular reflector with a large impedance change next to lung",["It attenuates little","It is a Rayleigh scatterer","Of aliasing"],"The pericardium and the air-filled lung behind it form a strong reflecting boundary.","C"),
(A,"Which type of reflection depends least on the beam angle?","Scattering (backscatter)",["Specular reflection","Mirror reflection","Total internal reflection"],"Scattered echoes return in many directions, so they appear from most transducer angles.","F"),
(A,"An attenuation coefficient of 2 dB/cm means a 5 cm round trip (2.5 cm deep) causes:","10 dB of attenuation",["2.5 dB","5 dB","20 dB"],"Total attenuation = coefficient × total path length = 2 × 5 = 10 dB.","C"),
(A,"Gain (amplification) differs from output power because gain:","Changes only the brightness of received echoes, not patient exposure",["Increases patient exposure","Changes the transmitted frequency","Changes propagation speed"],"Following ALARA, raise receiver gain before raising output power when the image is too dark.","F"),
]
